mapper.select:
select  from wo_notification_template

    event_code = #{eventCode}
    and category = #{category}
    and channel = #{channel}
    and enabled_flag = #{enabledFlag}

order by category, event_code, channel

mapper.update:
update wo_notification_template
set template_name = #{templateName}, title_template = #{titleTemplate},
    content_template = #{contentTemplate}, enabled_flag = #{enabledFlag},
    max_retry = #{maxRetry}, update_by = #{updateBy}, update_time = #{updateTime},
    remark = #{remark}
where id = #{id}

mapper.select:
select id, task_id, recipient_id, category, event_code, title, content, business_type,
       business_id, order_no, route_path, route_params, read_flag, read_at, create_time
from wo_notification_message
where recipient_id = #{recipientId}

    and category = #{query.category}


    and read_flag = #{query.readStatus}

order by create_time desc, id desc

mapper.update:
update wo_notification_message set read_flag = '1', read_at = #{readAt}
where recipient_id = #{recipientId} and read_flag = '0'
and category = #{category}

update wo_notification_task
set status = 'PROCESSING', locked_by = #{workerId}, locked_at = #{now}, update_time = #{now}
where id = #{id}
  and ((status in ('PENDING', 'RETRY') and next_retry_at <= #{now})
    or (status = 'PROCESSING' and locked_at <= #{lockExpiredAt}))

update wo_notification_task set status = 'SUCCESS', sent_at = #{sentAt}, update_time = #{sentAt},
    locked_by = null, locked_at = null, last_error = null
where id = #{id} and status = 'PROCESSING' and locked_by = #{workerId}

mapper.select:
select  from wo_notification_task t
left join wo_order o on o.id = t.business_id and t.business_type = 'WORK_ORDER'
left join sys_user u on u.user_id = o.applicant_id
left join sys_dept d on d.dept_id = o.applicant_dept_id

    t.status = #{status}
    and t.channel = #{channel}
    and t.category = #{category}
    and t.event_code = #{eventCode}
    and t.order_no like concat('%', #{orderNo}, '%')
    ${params.dataScope}

order by t.create_time desc, t.id desc

mapper.update:
update wo_notification_task set status = 'PENDING', retry_count = 0, next_retry_at = #{now},
    locked_by = null, locked_at = null, last_error = null, update_time = #{now}
where id = #{id} and status in ('RETRY', 'DEAD')
